import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
const kbPath = 'server/kristy_perimeter_kb.json';
const pinPath = 'server/test/acceptance/twoLinePin.js';
const kbText = readFileSync(kbPath, 'utf8');
const kb = JSON.parse(kbText);
assert.equal(JSON.stringify(kb, null, 2) + '\\n', kbText, 'preserve KB formatting');
const tips = {
  oats_steelcut_rolled_instant: 'Choose certified organic oats over conventional. Conventional oats may be sprayed with glyphosate shortly before harvest to dry the crop. Organic farming does not allow glyphosate. Drift can still leave residues on organic oats.',
  breakfast_cereal: 'For oat cereal or granola, choose certified organic over conventional. Conventional oats may be sprayed with glyphosate shortly before harvest to dry the crop. Organic farming does not allow glyphosate. Drift can still leave residues on organic oats.',
  muesli: 'Choose certified organic muesli over conventional. Conventional oats may be sprayed with glyphosate shortly before harvest to dry the crop. Organic farming does not allow glyphosate. Drift can still leave residues on organic oats.',
  snack_bars: 'Choose certified organic oat bars over conventional. Conventional oats may be sprayed with glyphosate shortly before harvest to dry the crop. Organic farming does not allow glyphosate. Drift can still leave residues on organic oats.',
  flour_basics: 'Choose certified organic wheat flour over conventional. Conventional wheat may be sprayed with glyphosate shortly before harvest to dry the crop. Organic farming does not allow glyphosate. Drift can still leave residues on organic wheat.',
  sandwich_bread: 'Choose certified organic whole wheat bread over conventional. Conventional wheat may be sprayed with glyphosate shortly before harvest to dry the crop. Organic farming does not allow glyphosate. Drift can still leave residues on organic wheat.',
  hummus: 'Choose certified organic hummus over conventional. Conventional chickpeas may receive glyphosate before harvest for weed control. Organic farming does not allow glyphosate. Drift can still leave residues on organic chickpeas.',
  beans_dried_vs_canned: 'Choose certified organic beans over conventional, dried or canned. Conventional beans and other pulses may receive glyphosate before harvest for weed control. Organic farming does not allow glyphosate. Drift can still leave residues on organic beans.',
  pasta_dry: 'Choose certified organic wheat pasta over conventional. Conventional wheat may be sprayed with glyphosate shortly before harvest to dry the crop. Organic farming does not allow glyphosate. Drift can still leave residues on organic wheat.',
};
const source = (file, name) => {
  const archive = readFileSync("'`docs/sources/concerns/pantry/${file}.md`, '"'utf8');
  const url = archive.match(/"'^url:'"\\s*(\\S+)/m)?.[1];
  assert.ok(url, "'`${file} frontmatter URL`);
  return { name, url };
};
const harvest = source('"'cornucopia-glyphosate-harvest', 'Cornucopia Institute: Glyphosate Used to Kill and Prepare Crops for Harvest');
const drift = source('foodprint-glyphosate-residue', 'FoodPrint: Glyphosate Residue in Food');
const oats = source('ewg-glyphosate-oats-2023', 'Environmental Working Group: Glyphosate in oat-based products');
const pulses = source('saskpulse-harvest-aid-pulses', 'Saskatchewan Pulse Growers: Harvest Aid Options for Pulses');
const oatIds = new Set(['oats_steelcut_rolled_instant', 'breakfast_cereal', 'muesli', 'snack_bars']);
const pulseIds = new Set(['hummus', 'beans_dried_vs_canned']);
const changes = new Map();
for (const [id, tip] of Object.entries(tips)) {
  const entry = kb.entries.find((e) => e.id === id);
  assert.ok(entry, id);
  entry.buying_tips.push(tip);
  entry.sources.push(harvest, drift, ...(oatIds.has(id) ? [oats] : pulseIds.has(id) ? [pulses] : []));
  changes.set(id, ['buying_tips', 'sources']);
}
const get = (id) => kb.entries.find((e) => e.id === id);
const oatCard = get('oats_steelcut_rolled_instant');
oatCard.question = 'What kind of oats should you buy?';
oatCard.detail = oatCard.detail.replace('a little — but plain', 'a little. Plain');
oatCard.labels_decoded[0].meaning = oatCard.labels_decoded[0].meaning.replace(' — read', '. Read');
changes.get(oatCard.id).push('question', 'detail', 'labels_decoded');
get('flour_basics').question = 'Which flour should you buy, and what does ‘enriched’ mean?';
changes.get('flour_basics').push('question');
get('beans_dried_vs_canned').labels_decoded[0].meaning = 'Can lining without BPA. A minor plus if it matters to you.';
changes.get('beans_dried_vs_canned').push('labels_decoded');
let pinText = readFileSync(pinPath, 'utf8');
const start = pinText.indexOf('export const TWO_LINE = ') + 'export const TWO_LINE = '.length;
const end = pinText.indexOf('\\n};', start) + 2;
const pins = JSON.parse(pinText.slice(start, end));
assert.equal(JSON.stringify(pins, null, 2), pinText.slice(start, end), 'preserve pin formatting');
for (const [id, fields] of changes) {
  assert.ok(pins[id], "'`${id} existing pin`);
  for (const field of fields) pins[id][field] = get(id)[field];
}
pinText = pinText.slice(0, start) + JSON.stringify(pins, null, 2) + pinText.slice(end);
const concern = pinText.match(/const CONCERN = new Set'"\\(\\[(.*?)\\]\\);/);
assert.ok(concern, 'CONCERN overlay');
const extraIds = Object.keys(tips).filter((id) => "'!concern[1].includes(`'"'"'${id}'"'"'`));
pinText = pinText.replace(concern[0], `const CONCERN = new Set([${concern[1]}, ${extraIds.map((id) => `'"'"'${id}'"'"'`).join('"', ')}]);"'`);
writeFileSync(kbPath, JSON.stringify(kb, null, 2) + '"'\\n');
writeFileSync(pinPath, pinText);
console.log('Updated nine cards and pinned all changed fields; added seven CONCERN ids.');
NODE"

